args.command:
grep -o '"[^"]*mail[^"]*"' ~/.agentic-corpus.json 2>/dev/null | head -20; echo "---"; python3 -c "
import json
with open('<home>/.agentic-corpus.json') as f:
    data = json.load(f)
print(type(data))
if isinstance(data, dict):
    for k in data:
        if 'mail' in k.lower():
            print(k)
elif isinstance(data, list):
    for item in data:
        if 'mail' in json.dumps(item).lower():
            print(json.dumps(item)[:500])
" 2>/dev/null | head -40

python3 -c "
import json
with open('<home>/.agentic-corpus.json') as f:
    data = json.load(f)
print(type(data))
if isinstance(data, dict):
    for k in data:
        if 'mail' in k.lower():
            print('KEY:', k)
elif isinstance(data, list):
    for item in data:
        s = json.dumps(item)
        if 'mail' in s.lower():
            print(s[:800])
" 2>/dev/null | head -60
